I understand you need a JavaScript function to update the time displayed on a webpage in real-time. I can provide you with a solution without needing to call any external tools.

Here's a JavaScript function that will update the time in real-time:

```javascript
function updateRealTimeClock() {
    // Function to update the time display
    function updateTime() {
        const now = new Date();

        // Format time as HH:MM:SS
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        const seconds = String(now.getSeconds()).padStart(2, '0');

        const timeString = `${hours}:${minutes}:${seconds}`;

        // Update the element with id 'clock' or create one if it doesn't exist
        let clockElement = document.getElementById('clock');
        if (!clockElement) {
            clockElement = document.createElement('div');
            clockElement.id = 'clock';
            document.body.appendChild(clockElement);
        }

        clockElement.textContent = timeString;
    }

    // Update immediately
    updateTime();

    // Update every second (1000 milliseconds)
    setInterval(updateTime, 1000);
}

// To use this function, call it when the page loads:
// window.addEventListener('DOMContentLoaded', updateRealTimeClock);
```

