```javascript
function updateRealTimeClock(elementId = 'clock', showSeconds = true, format24h = true) {
    function updateTime() {
        const now = new Date();
        let hours = now.getHours();
        let minutes = now.getMinutes();
        let seconds = now.getSeconds();

        // Handle 12-hour format if needed
        let ampm = '';
        if (!format24h) {
            ampm = hours >= 12 ? ' PM' : ' AM';
            hours = hours % 12;
            hours = hours ? hours : 12; // the hour '0' should be '12'
        }

        hours = String(hours).padStart(2, '0');
        minutes = String(minutes).padStart(2, '0');
        seconds = String(seconds).padStart(2, '0');

        const timeString = showSeconds 
            ? `${hours}:${minutes}:${seconds}${ampm}` 
            : `${hours}:${minutes}${ampm}`;

        let clockElement = document.getElementById(elementId);
        if (clockElement) {
            clockElement.textContent = timeString;
        }
    }

    updateTime();
    setInterval(updateTime, 1000);
}
```

This function creates a real-time clock that updates every second. You can customize it by passing different parameters to format the time display according to your needs.

