// browser-security-warnings-disabler.js
// Utility to disable security warnings in browser console for development

class BrowserSecurityWarningsDisabler {
    constructor() {
        this.isEnabled = false;
        this.originalConsoleWarn = null;
        this.originalConsoleError = null;
        this.filteredWarnings = [
            'Mixed Content',
            'Content Security Policy',
            'Cross-Origin',
            'CORS',
            'SSL',
            'Certificate',
            'Security',
            'Deprecation',
            'violation',
            'blocked'
        ];
    }

    /**
     * Enable security warnings filtering
     */
    enable() {
        if (this.isEnabled) {
            console.log('Security warnings filtering is already enabled');
            return;
        }

        // Store original console methods
        this.originalConsoleWarn = console.warn;
        this.originalConsoleError = console.error;

        // Override console.warn
        console.warn = (...args) => {
            const message = args.join(' ').toLowerCase();
            const shouldFilter = this.filteredWarnings.some(warning => 
                message.includes(warning.toLowerCase())
            );

            if (!shouldFilter) {
                this.originalConsoleWarn.apply(console, args);
            }
        };

        // Override console.error
        console.error = (...args) => {
            const message = args.join(' ').toLowerCase();
            const shouldFilter = this.filteredWarnings.some(warning => 
                message.includes(warning.toLowerCase())
            );

            if (!shouldFilter) {
                this.originalConsoleError.apply(console, args);
            }
        };

        // Additional browser-specific security warning suppression
        this.suppressBrowserSpecificWarnings();

        this.isEnabled = true;
        console.log('🔧 Security warnings filtering enabled');
    }

    /**
     * Disable security warnings filtering and restore original console methods
     */
    disable() {
        if (!this.isEnabled) {
            console.log('Security warnings filtering is not enabled');
            return;
        }

        // Restore original console methods
        if (this.originalConsoleWarn) {
            console.warn = this.originalConsoleWarn;
        }
        if (this.originalConsoleError) {
            console.error = this.originalConsoleError;
        }

        this.isEnabled = false;
        console.log('🔧 Security warnings filtering disabled');
    }

    /**
     * Browser-specific security warning suppression methods
     */
    suppressBrowserSpecificWarnings() {
        // Suppress mixed content warnings
        if (window.location.protocol === 'https:') {
            // This helps with mixed content warnings during development
            const meta = document.createElement('meta');
            meta.httpEquiv = 'Content-Security-Policy';
            meta.content = "upgrade-insecure-requests";
            document.head.appendChild(meta);
        }

        // Suppress CORS-related warnings for development
        this.setupCORSProxy();

        // Monkey patch XMLHttpRequest and fetch to suppress CORS warnings
        this.patchNetworkRequests();
    }

    /**
     * Setup simple CORS proxy for development
     */
    setupCORSProxy() {
        // This is a basic approach - in real scenarios, use proper CORS middleware
        const originalFetch = window.fetch;
        window.fetch = async (...args) => {
            try {
                return await originalFetch.apply(window, args);
            } catch (error) {
                if (error.message.includes('CORS') || error.message.includes('cross-origin')) {
                    console.log('🔧 CORS warning suppressed for development');
                    return new Response(null, { status: 200 });
                }
                throw error;
            }
        };
    }

    /**
     * Patch XMLHttpRequest to handle CORS gracefully
     */
    patchNetworkRequests() {
        const OriginalXHR = window.XMLHttpRequest;
        const self = this;

        window.XMLHttpRequest = function() {
            const xhr = new OriginalXHR();
            const originalOpen = xhr.open;
            const originalSend = xhr.send;

            xhr.open = function(method, url, async, user, password) {
                this._url = url;
                return originalOpen.call(this, method, url, async !== false, user, password);
            };

            xhr.send = function(data) {
                this.addEventListener('error', function() {
                    if (this._url && this._url.includes('http')) {
                        console.log('🔧 Network error suppressed for development');
                    }
                });
                return originalSend.call(this, data);
            };

            return xhr;
        };
    }

    /**
     * Add custom warning patterns to filter
     * @param {string[]} patterns - Array of warning patterns to filter
     */
    addFilterPatterns(patterns) {
        this.filteredWarnings = [...this.filteredWarnings, ...patterns];
    }

    /**
     * Remove specific warning patterns from filtering
     * @param {string[]} patterns - Array of warning patterns to remove
     */
    removeFilterPatterns(patterns) {
        this.filteredWarnings = this.filteredWarnings.filter(
            pattern => !patterns.includes(pattern)
        );
    }

    /**
     * Get current filtering status
     */
    getStatus() {
        return {
            enabled: this.isEnabled,
            filteredPatterns: this.filteredWarnings,
            originalMethodsPreserved: !!(this.originalConsoleWarn && this.originalConsoleError)
        };
    }
}

