I'll create a JavaScript function that handles file uploads from a private directory to a public URL. This is a common task for enabling content sharing between users.

```javascript
/**
 * Function to upload files from a private directory to a public URL for sharing
 * @param {File|FileList} files - File or FileList object containing the files to upload
 * @param {string} uploadEndpoint - API endpoint for file upload
 * @param {Object} options - Additional options for the upload process
 * @returns {Promise<Object>} - Promise that resolves with upload response containing public URLs
 */
async function uploadFilesForSharing(files, uploadEndpoint, options = {}) {
    try {
        // Validate input parameters
        if (!files) {
            throw new Error('Files parameter is required');
        }

        if (!uploadEndpoint) {
            throw new Error('Upload endpoint is required');
        }

        // Convert single file to array for consistent processing
        const fileArray = files instanceof FileList ? Array.from(files) : [files];

        if (fileArray.length === 0) {
            throw new Error('No valid files provided');
        }

        // Prepare form data for upload
        const formData = new FormData();

        // Add each file to form data
        fileArray.forEach((file, index) => {
            // Validate file type and size if options provided
            if (options.allowedTypes && !options.allowedTypes.includes(file.type)) {
                throw new Error(`File type ${file.type} is not allowed`);
            }

            if (options.maxSize && file.size > options.maxSize) {
                throw new Error(`File ${file.name} exceeds maximum size limit`);
            }

            formData.append('files', file);
        });

        // Add additional metadata if provided
        if (options.metadata) {
            formData.append('metadata', JSON.stringify(options.metadata));
        }

        // Configure fetch options
        const fetchOptions = {
            method: 'POST',
            body: formData,
            headers: {
                // Authorization header if needed
                ...(options.authToken && { 'Authorization': `Bearer ${options.authToken}` }),
            },
        };

        // Execute upload request
        const response = await fetch(uploadEndpoint, fetchOptions);

        if (!response.ok) {
            throw new Error(`Upload failed with status: ${response.status}`);
        }

        const result = await response.json();

        // Return public URLs and file information
        return {
            success: true,
            publicUrls: result.publicUrls || [],
            fileInfo: result.fileInfo || [],
            message: 'Files uploaded successfully and ready for sharing'
        };

    } catch (error) {
        console.error('File upload error:', error);
        return {
            success: false,
            error: error.message,
            publicUrls: [],
            fileInfo: []
        };
    }
}

/**
 * Helper function to generate shareable links with optional expiration
 * @param {Array} publicUrls - Array of public URLs from upload
 * @param {Object} shareOptions - Options for link generation
 * @returns {Object} - Object containing shareable links and metadata
 */
function generateShareableLinks(publicUrls, shareOptions = {}) {
    const links = publicUrls.map(url => {
        let shareableUrl = url;

        // Add expiration if specified
        if (shareOptions.expiresIn) {
            const expirationTime = new Date(Date.now() + shareOptions.expiresIn).toISOString();
            shareableUrl += `?expires=${encodeURIComponent(expirationTime)}`;
        }

        // Add password protection if specified
        if (shareOptions.password) {
            const separator = shareableUrl.includes('?') ? '&' : '?';
            shareableUrl += `${separator}protected=true`;
        }

        return {
            url: shareableUrl,
            originalUrl: url,
            expires: shareOptions.expiresIn ? new Date(Date.now() + shareOptions.expiresIn) : null,
            passwordProtected: !!shareOptions.password
        };
    });

    return {
        links,
        totalFiles: publicUrls.length,
        generatedAt: new Date().toISOString()
    };
}

