// Real-time Note Synchronization System

// 1. WebSocket Connection Manager
class SyncManager {
    constructor() {
        this.ws = null;
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = 5;
        this.pendingChanges = [];
        this.isOnline = navigator.onLine;
        this.setupEventListeners();
    }

    connect() {
        try {
            this.ws = new WebSocket('wss://your-server.com/notes-sync');

            this.ws.onopen = () => {
                console.log('WebSocket connected');
                this.reconnectAttempts = 0;
                this.processPendingChanges();
            };

            this.ws.onmessage = (event) => {
                this.handleIncomingChange(JSON.parse(event.data));
            };

            this.ws.onclose = () => {
                console.log('WebSocket disconnected');
                this.attemptReconnect();
            };

            this.ws.onerror = (error) => {
                console.error('WebSocket error:', error);
            };

        } catch (error) {
            console.error('WebSocket connection failed:', error);
        }
    }

    attemptReconnect() {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            setTimeout(() => this.connect(), Math.min(1000 * this.reconnectAttempts, 10000));
        }
    }

    setupEventListeners() {
        window.addEventListener('online', () => {
            this.isOnline = true;
            this.connect();
        });

        window.addEventListener('offline', () => {
            this.isOnline = false;
        });
    }
}

// 2. Conflict Resolution System
class ConflictResolver {
    constructor() {
        this.version = 0;
        this.lastSynced = null;
    }

    // Operational Transform for concurrent edits
    transformChanges(localChange, remoteChange) {
        if (localChange.timestamp > remoteChange.timestamp) {
            return this.resolveTimestampConflict(localChange, remoteChange);
        }
        return remoteChange;
    }

    resolveTimestampConflict(local, remote) {
        // Simple last-write-wins with content merging for text
        if (local.type === 'text-edit' && remote.type === 'text-edit') {
            return this.mergeTextEdits(local, remote);
        }
        return local.timestamp > remote.timestamp ? local : remote;
    }

    mergeTextEdits(local, remote) {
        // Basic text merging - in production, use a proper OT library
        const mergedContent = local.content + '\n' + remote.content;
        return {
            ...local,
            content: mergedContent,
            merged: true
        };
    }
}

// 3. Local Storage Manager for Offline Support
class LocalStorageManager {
    constructor() {
        this.storageKey = 'notes-app-data';
    }

    saveLocally(noteData) {
        try {
            localStorage.setItem(this.storageKey, JSON.stringify(noteData));
            return true;
        } catch (error) {
            console.error('Local storage save failed:', error);
            return false;
        }
    }

    loadLocally() {
        try {
            const data = localStorage.getItem(this.storageKey);
            return data ? JSON.parse(data) : null;
        } catch (error) {
            console.error('Local storage load failed:', error);
            return null;
        }
    }

    clearLocal() {
        localStorage.removeItem(this.storageKey);
    }
}

// 4. Real-time Note Editor Component
class RealTimeNoteEditor {
    constructor() {
        this.syncManager = new SyncManager();
        this.conflictResolver = new ConflictResolver();
        this.storageManager = new LocalStorageManager();
        this.currentNote = null;
        this.debounceTimer = null;
        this.init();
    }

    init() {
        this.syncManager.connect();
        this.loadNote();
        this.setupEditorEvents();
    }

    setupEditorEvents() {
        const editor = document.getElementById('note-editor');

        editor.addEventListener('input', (e) => {
            this.debounce(() => {
                this.handleLocalChange(e.target.value);
            }, 300);
        });

        // Handle paste events for rich content
        editor.addEventListener('paste', (e) => {
            e.preventDefault();
            const text = e.clipboardData.getData('text/plain');
            document.execCommand('insertText', false, text);
        });
    }

    debounce(func, wait) {
        clearTimeout(this.debounceTimer);
        this.debounceTimer = setTimeout(func, wait);
    }

    handleLocalChange(content) {
        const change = {
            type: 'text-edit',
            content: content,
            timestamp: Date.now(),
            noteId: this.currentNote?.id,
            version: this.conflictResolver.version++
        };

        // Save locally immediately
        this.storageManager.saveLocally({
            ...this.currentNote,
            content: content,
            lastModified: Date.now()
        });

        // Queue for sync
        if (this.syncManager.isOnline) {
            this.syncManager.sendChange(change);
        } else {
            this.syncManager.queueChange(change);
        }
    }

    handleIncomingChange(change) {
        if (change.noteId === this.currentNote?.id) {
            this.applyRemoteChange(change);
        }
    }

    applyRemoteChange(change) {
        const editor = document.getElementById('note-editor');
        const currentContent = editor.value;

        // Only update if content is different to avoid cursor jumps
        if (currentContent !== change.content) {
            editor.value = change.content;

            // Trigger change event for any listeners
            editor.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }

    loadNote() {
        // Load from local storage first for instant startup
        const localData = this.storageManager.loadLocally();
        if (localData) {
            this.currentNote = localData;
            this.renderNote();
        }

        // Then attempt to sync with server
        this.syncManager.requestLatestVersion();
    }

    renderNote() {
        const editor = document.getElementById('note-editor');
        if (this.currentNote) {
            editor.value = this.currentNote.content;
        }
    }
}

