```javascript
class SimpleEncryption {
    constructor() {
        this.algorithm = 'AES-GCM';
        this.keyLength = 256;
    }

    // Generate a cryptographic key
    async generateKey() {
        try {
            const key = await window.crypto.subtle.generateKey(
                {
                    name: this.algorithm,
                    length: this.keyLength
                },
                true,
                ['encrypt', 'decrypt']
            );
            return key;
        } catch (error) {
            console.error('Error generating key:', error);
            throw error;
        }
    }

    // Export key to string format for storage
    async exportKey(key) {
        try {
            const exported = await window.crypto.subtle.exportKey('raw', key);
            const exportedKeyBuffer = new Uint8Array(exported);
            return Array.from(exportedKeyBuffer).map(b => b.toString(16).padStart(2, '0')).join('');
        } catch (error) {
            console.error('Error exporting key:', error);
            throw error;
        }
    }

    // Import key from string format
    async importKey(keyString) {
        try {
            const keyBuffer = new Uint8Array(keyString.match(/.{1,2}/g).map(byte => parseInt(byte, 16)));
            const key = await window.crypto.subtle.importKey(
                'raw',
                keyBuffer,
                { name: this.algorithm },
                true,
                ['encrypt', 'decrypt']
            );
            return key;
        } catch (error) {
            console.error('Error importing key:', error);
            throw error;
        }
    }

    // Encrypt data
    async encrypt(data, key) {
        try {
            const encoder = new TextEncoder();
            const dataBuffer = encoder.encode(data);

            // Generate initialization vector
            const iv = window.crypto.getRandomValues(new Uint8Array(12));

            const encrypted = await window.crypto.subtle.encrypt(
                {
                    name: this.algorithm,
                    iv: iv
                },
                key,
                dataBuffer
            );

            // Combine IV and encrypted data
            const result = new Uint8Array(iv.length + encrypted.byteLength);
            result.set(iv, 0);
            result.set(new Uint8Array(encrypted), iv.length);

            return btoa(String.fromCharCode(...result));
        } catch (error) {
            console.error('Error encrypting data:', error);
            throw error;
        }
    }

    // Decrypt data
    async decrypt(encryptedData, key) {
        try {
            // Convert from base64
            const encryptedBuffer = Uint8Array.from(atob(encryptedData), c => c.charCodeAt(0));

            // Extract IV (first 12 bytes)
            const iv = encryptedBuffer.slice(0, 12);
            const data = encryptedBuffer.slice(12);

            const decrypted = await window.crypto.subtle.decrypt(
                {
                    name: this.algorithm,
                    iv: iv
                },
                key,
                data
            );

            const decoder = new TextDecoder();
            return decoder.decode(decrypted);
        } catch (error) {
            console.error('Error decrypting data:', error);
            throw error;
        }
    }
}

// Example usage:
async function exampleUsage() {
    const crypto = new SimpleEncryption();

    try {
        // Generate a key
        const key = await crypto.generateKey();
        console.log('Key generated');

        // Export the key for storage
        const keyString = await crypto.exportKey(key);
        console.log('Exported key:', keyString);

        // Data to encrypt
        const sensitiveData = 'This is my sensitive user data';

        // Encrypt the data
        const encrypted = await crypto.encrypt(sensitiveData, key);
        console.log('Encrypted data:', encrypted);

        // Import the key back
        const importedKey = await crypto.importKey(keyString);

        // Decrypt the data
        const decrypted = await crypto.decrypt(encrypted, importedKey);
        console.log('Decrypted data:', decrypted);

        return {
            key: keyString,
            encryptedData: encrypted,
            decryptedData: decrypted
        };
    } catch (error) {
        console.error('Encryption example failed:', error);
    }
}

// Utility function to encrypt data with password (using PBKDF2 for key derivation)
async function encryptWithPassword(data, password) {
    try {
        const encoder = new TextEncoder();

        // Generate salt
        const salt = window.crypto.getRandomValues(new Uint8Array(16));

        // Derive key from password
        const baseKey = await window.crypto.subtle.importKey(
            'raw',
            encoder.encode(password),
            'PBKDF2',
            false,
            ['deriveKey']
        );

        const key = await window.crypto.subtle.deriveKey(
            {
                name: 'PBKDF2',
                salt: salt,
                iterations: 100000,
                hash: 'SHA-256'
            },
            baseKey,
            { name: 'AES-GCM', length: 256 },
            false,
            ['encrypt', 'decrypt']
        );

        const encrypted = await new SimpleEncryption().encrypt(data, key);

        // Combine salt and encrypted data
        const result = btoa(String.fromCharCode(...salt)) + '.' + encrypted;
        return result;
    } catch (error) {
        console.error('Error encrypting with password:', error);
        throw error;
    }
}

// Utility function to decrypt data with password
async function decryptWithPassword(encryptedData, password) {
    try {
        const encoder = new TextEncoder();
        const [saltBase64, data] = encryptedData.split('.');

        // Extract salt
        const salt = Uint8Array.from(atob(saltBase64), c => c.charCodeAt(0));

        // Derive key from password
        const baseKey = await window.crypto.subtle.importKey(
            'raw',
            encoder.encode(password),
            'PBKDF2',
            false,
            ['deriveKey']
        );

        const key = await window.crypto.subtle.deriveKey(
            {
                name: 'PBKDF2',
                salt: salt,
                iterations: 100000,
                hash: 'SHA-256'
            },
            baseKey,
            { name: 'AES-GCM', length: 256 },
            false,
            ['encrypt', 'decrypt']
        );

        const decrypted = await new SimpleEncryption().decrypt(data, key);
        return decrypted;
    } catch (error) {
        console.error('Error decrypting with password:', error);
        throw error;
    }
}

export { SimpleEncryption, encryptWithPassword, decryptWithPassword };
