class DiscountCodeManager {
    constructor() {
        // Sample user groups (you would replace this with your actual user data)
        this.userGroups = {
            'vip': ['user1@email.com', 'user2@email.com', 'user3@email.com'],
            'new-customers': ['newuser1@email.com', 'newuser2@email.com'],
            'loyal': ['loyaluser@email.com', 'longterm@email.com']
        };

        // Generated discount codes storage
        this.generatedCodes = new Map();
    }

    // Generate random discount code
    generateDiscountCode(length = 8, prefix = 'SAVE') {
        const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let randomPart = '';

        for (let i = 0; i < length; i++) {
            randomPart += characters.charAt(Math.floor(Math.random() * characters.length));
        }

        return `${prefix}${randomPart}`;
    }

    // Create discount settings for different user groups
    createDiscountForGroup(groupName, discountType, value, expirationDays = 30) {
        const discountCode = this.generateDiscountCode();
        const expirationDate = new Date();
        expirationDate.setDate(expirationDate.getDate() + expirationDays);

        const discountInfo = {
            code: discountCode,
            type: discountType, // 'percentage' or 'fixed'
            value: value,
            group: groupName,
            expiration: expirationDate,
            isActive: true
        };

        this.generatedCodes.set(discountCode, discountInfo);
        return discountInfo;
    }

    // Check if current user should see a discount
    shouldShowDiscount(userEmail, userGroup) {
        // Check if user belongs to the specified group
        const groupUsers = this.userGroups[userGroup];
        if (!groupUsers || !groupUsers.includes(userEmail)) {
            return false;
        }

        // Check if there's an active discount for this group
        const activeDiscounts = Array.from(this.generatedCodes.values())
            .filter(discount => 
                discount.group === userGroup && 
                discount.isActive && 
                new Date(discount.expiration) > new Date()
            );

        return activeDiscounts.length > 0;
    }

    // Get discount code for specific user and group
    getDiscountForUser(userEmail, userGroup) {
        if (!this.shouldShowDiscount(userEmail, userGroup)) {
            return null;
        }

        const groupDiscounts = Array.from(this.generatedCodes.values())
            .filter(discount => 
                discount.group === userGroup && 
                discount.isActive && 
                new Date(discount.expiration) > new Date()
            );

        return groupDiscounts.length > 0 ? groupDiscounts[0] : null;
    }

    // Display discount code on the website
    displayDiscountCode(userEmail, userGroup, containerId) {
        const discount = this.getDiscountForUser(userEmail, userGroup);
        const container = document.getElementById(containerId);

        if (!container) {
            console.error('Discount container not found');
            return;
        }

        if (discount) {
            container.innerHTML = `
                <div class="discount-banner">
                    <h3>Special Offer for ${userGroup} Members!</h3>
                    <p>Use code: <strong>${discount.code}</strong></p>
                    <p>Get ${discount.value}${discount.type === 'percentage' ? '%' : '$'} off</p>
                    <p>Expires: ${discount.expiration.toLocaleDateString()}</p>
                </div>
            `;
            container.style.display = 'block';
        } else {
            container.style.display = 'none';
        }
    }

