    initializeDefaults() {
        // Create sample discounts for different groups
        this.createDiscountForGroup('vip', 'percentage', 20, 60); // 20% off for 60 days
        this.createDiscountForGroup('new-customers', 'fixed', 15, 14); // $15 off for 14 days
        this.createDiscountForGroup('loyal', 'percentage', 10, 30); // 10% off for 30 days
    }
}

