    }

    /**
     * Create formatted log entry
     */
    private function createLogEntry($username, $ipAddress, $success, $userAgent, $additionalData) {
        $timestamp = date('Y-m-d H:i:s');
        $status = $success ? 'SUCCESS' : 'FAILED';
        $userAgent = $userAgent ?: ($_SERVER['HTTP_USER_AGENT'] ?? 'Unknown');

        $logData = [
            'timestamp' => $timestamp,
            'username' => $username,
            'ip_address' => $ipAddress,
            'status' => $status,
            'user_agent' => substr($userAgent, 0, 200) // Limit length
        ];

        // Add additional data if provided
        if (!empty($additionalData)) {
            $logData['additional_data'] = json_encode($additionalData);
        }

        // Format as CSV for easy parsing
        $logLine = implode('|', array_map(function($value) {
            return str_replace('|', '\\|', $value);
        }, $logData)) . PHP_EOL;

        return $logLine;
    }

    /**
     * Rotate log file if it becomes too large
     */
    private function rotateLogIfNeeded() {
        if (file_exists($this->logFile) && filesize($this->logFile) > $this->maxFileSize) {
            $this->rotateLog();
        }
    }

    /**
     * Rotate log file
     */
    private function rotateLog() {
        for ($i = $this->maxBackupFiles - 1; $i >= 0; $i--) {
            $oldFile = $this->logFile . '.' . $i;
            $newFile = $this->logFile . '.' . ($i + 1);

            if (file_exists($oldFile)) {
                if ($i + 1 < $this->maxBackupFiles) {
                    rename($oldFile, $newFile);
                } else {
                    unlink($oldFile);
                }
            }
        }

        if (file_exists($this->logFile)) {
            rename($this->logFile, $this->logFile . '.0');
        }
    }

    /**
     * Ensure log directory exists
     */
    private function ensureLogDirectory() {
        $dir = dirname($this->logFile);
        if (!is_dir($dir) && $dir !== '.') {
            mkdir($dir, 0755, true);
        }
    }

    /**
     * Read and parse log entries for analysis
     */
    public function analyzeLogs($limit = 1000, $filters = []) {
        if (!file_exists($this->logFile)) {
            return [];
        }

        $lines = file($this->logFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
        $entries = [];
        $count = 0;

        // Read from end (most recent first)
        for ($i = count($lines) - 1; $i >= 0 && $count < $limit; $i--) {
            $entry = $this->parseLogEntry($lines[$i]);

            if ($entry && $this->applyFilters($entry, $filters)) {
                $entries[] = $entry;
                $count++;
            }
        }

        return array_reverse($entries); // Return in chronological order
    }

    /**
     * Parse a single log entry
     */
    private function parseLogEntry($line) {
        $parts = array_map(function($part) {
            return str_replace('\\|', '|', $part);
        }, explode('|', $line));

        if (count($parts) < 5) return null;

        return [
            'timestamp' => $parts[0],
            'username' => $parts[1],
            'ip_address' => $parts[2],
            'status' => $parts[3],
            'user_agent' => $parts[4],
            'additional_data' => isset($parts[5]) ? json_decode($parts[5], true) : []
        ];
    }

    /**
     * Apply filters to log entries
     */
    private function applyFilters($entry, $filters) {
        foreach ($filters as $key => $value) {
            if (!isset($entry[$key]) || $entry[$key] != $value) {
                return false;
            }
        }
        return true;
    }

    /**
     * Get login statistics
     */
    public function getStatistics($hoursBack = 24) {
        $cutoffTime = time() - ($hoursBack * 3600);
        $entries = $this->analyzeLogs();

        $stats = [
            'total_attempts' => 0,
            'successful_logins' => 0,
            'failed_logins' => 0,
            'unique_users' => [],
            'unique_ips' => [],
            'hourly_breakdown' => []
        ];

        foreach ($entries as $entry) {
            $entryTime = strtotime($entry['timestamp']);
            if ($entryTime < $cutoffTime) continue;

            $stats['total_attempts']++;

            if ($entry['status'] === 'SUCCESS') {
                $stats['successful_logins']++;
            } else {
                $stats['failed_logins']++;
            }

            $stats['unique_users'][$entry['username']] = true;
            $stats['unique_ips'][$entry['ip_address']] = true;

            // Hourly breakdown
            $hour = date('H', $entryTime);
            if (!isset($stats['hourly_breakdown'][$hour])) {
                $stats['hourly_breakdown'][$hour] = ['success' => 0, 'failed' => 0];
            }

            if ($entry['status'] === 'SUCCESS') {
                $stats['hourly_breakdown'][$hour]['success']++;
