    <div id="location-info">
        <p>Detecting your location...</p>
    </div>

    <div id="regional-content" class="hidden">
        <h2>Content Tailored for Your Region</h2>
        <div id="content-container"></div>
    </div>

    <script>
        // Location detection function
        function getLocation() {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    showPosition,
                    handleLocationError,
                    { enableHighAccuracy: true, timeout: 10000 }
                );
            } else {
                document.getElementById('location-info').innerHTML = 
                    "Geolocation is not supported by this browser.";
            }
        }

        function showPosition(position) {
            const lat = position.coords.latitude;
            const lon = position.coords.longitude;

            // Display location info
            document.getElementById('location-info').innerHTML = 
                `Location detected: Latitude ${lat}, Longitude ${lon}`;

            // Get localized content
            fetchLocalizedContent(lat, lon);
        }

        function handleLocationError(error) {
            let message = "Unable to retrieve your location. ";
            switch(error.code) {
                case error.PERMISSION_DENIED:
                    message += "User denied the request for Geolocation.";
                    break;
                case error.POSITION_UNAVAILABLE:
                    message += "Location information is unavailable.";
                    break;
                case error.TIMEOUT:
                    message += "The request to get user location timed out.";
                    break;
                default:
                    message += "An unknown error occurred.";
                    break;
            }
            document.getElementById('location-info').innerHTML = message;
        }

        async function fetchLocalizedContent(lat, lon) {
            try {
                const response = await fetch(`/api/localized-content?lat=${lat}&lon=${lon}`);
                const data = await response.json();

                document.getElementById('regional-content').classList.remove('hidden');
                document.getElementById('content-container').innerHTML = 
                    `<h3>${data.region}</h3>
                     <p>${data.content}</p>
                     <p><small>Local time: ${data.localTime}</small></p>`;

                // Send analytics data
                sendAnalyticsData(lat, lon, data.region);

            } catch (error) {
                console.error('Error fetching localized content:', error);
            }
        }

        function sendAnalyticsData(lat, lon, region) {
            // Send to backend for storage
            fetch('/api/analytics', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    latitude: lat,
                    longitude: lon,
                    region: region,
                    timestamp: new Date().toISOString(),
                    userAgent: navigator.userAgent
                })
            });
        }

        // Initialize on page load
        document.addEventListener('DOMContentLoaded', getLocation);
    </script>
</body>
</html>
