```python
import hashlib
import secrets
import time
from typing import Optional, Dict
import jwt
from datetime import datetime, timedelta



class AuthenticationService:
    def __init__(self, secret_key: str, algorithm: str = "HS256"):
        self.secret_key = secret_key
        self.algorithm = algorithm
        self.failed_attempts:[str, int] = {}
        self.lockout_threshold = 5
        self.lockout_duration = 300  # 5 minutes

    def hash_password(self, password: str, salt: Optional[str] = None) -> tuple:
        """Hash password with salt using PBKDF2"""
        if salt is None:
            salt = secrets.token_hex(16)

        # Use PBKDF2 for secure password hashing
        hashed_password = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000  # 100,000 iterations
        ).hex()

        return hashed_password, salt

    def verify_password(self, password: str, hashed_password: str, salt: str) -> bool:
        """Verify password against stored hash"""
        new_hash, _ = self.hash_password(password, salt)
        return secrets.compare_digest(new_hash, hashed_password)

    def is_account_locked(self, username: str) -> bool:
        """Check if account is temporarily locked due to failed attempts"""
        if username in self.failed_attempts:
            if self.failed_attempts[username] >= self.lockout_threshold:
                return True
        return False

    def increment_failed_attempts(self, username: str):
        """Record failed login attempt"""
        if username not in self.failed_attempts:
            self.failed_attempts[username] = 0
        self.failed_attempts[username] += 1

    def reset_failed_attempts(self, username: str):
        """Reset failed attempts on successful login"""
        if username in self.failed_attempts:
            del self.failed_attempts[username]

    def generate_token(self, username: str, user_id: int, expires_hours: int = 24) -> str:
        """Generate JWT token for authenticated user"""
        payload = {
            'username': username,
            'user_id': user_id,
            'exp': datetime.utcnow() + timedelta(hours=expires_hours),
            'iat': datetime.utcnow()
        }
        return jwt.encode(payload, self.secret_key, algorithm=self.algorithm)

    def verify_token(self, token: str) -> Optional[dict]:
        """Verify and decode JWT token"""
        try:
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
            return payload
        except jwt.ExpiredSignatureError:
            return None
        except jwt.InvalidTokenError:
            return None

    def authenticate(self, username: str, password: str, user_database: dict) -> dict:
        """
        Main authentication method with security features
        Returns: dict with success status and token if successful
        """
        # Check if account is locked
        if self.is_account_locked(username):
            return {
                'success': False,
                'message': 'Account temporarily locked due to multiple failed attempts'
            }

        # Verify user exists and validate password
        if username in user_database:
            stored_hash = user_database[username]['password_hash']
            salt = user_database[username]['salt']

            if self.verify_password(password, stored_hash, salt):
                # Successful authentication
                self.reset_failed_attempts(username)
                token = self.generate_token(username, user_database[username]['user_id'])

                return {
                    'success': True,
                    'token': token,
                    'user_id': user_database[username]['user_id']
                }

        # Failed authentication
        self.increment_failed_attempts(username)
        return {
            'success': False,
            'message': 'Invalid username or password'
        }


# Example usage
if __name__ == "__main__":
    # Initialize authentication service
    auth_service = AuthenticationService(secret_key="your-secret-key-here")

    # Sample user database (in production, use a proper database)
    user_database = {
        "john_doe": {
            "user_id": 1,
            "password_hash": auth_service.hash_password("securepassword123")[0],
            "salt": auth_service.hash_password("securepassword123")[1]
        }
    }

    # Test authentication
    result = auth_service.authenticate("john_doe", "securepassword123", user_database)
    print(result)
```

This implementation includes several optimizations and security features:

1. **Password hashing** using PBKDF2 with salt
2. **Rate limiting** to prevent brute force attacks
3. **JWT token generation** for stateless authentication
4. **Secure password comparison** using constant-time comparison
5. **Account lockout** after multiple failed attempts
6. **Token expiration** for enhanced security

