            this.addInteraction(interaction);
        });
    }

    // Log mouse movements and clicks
    setupMouseListener() {
        let lastMouseMove = 0;
        const mouseMoveThrottle = 100; // ms

        // Mouse movement with throttling
        document.addEventListener('mousemove', (event) => {
            const now = Date.now();
            if (now - lastMouseMove > mouseMoveThrottle) {
                const interaction = {
                    type: 'mousemove',
                    x: event.clientX,
                    y: event.clientY,
                    timestamp: now,
                    target: this.getElementInfo(event.target)
                };
                this.addInteraction(interaction);
                lastMouseMove = now;
            }
        });

        // Mouse clicks
        document.addEventListener('click', (event) => {
            const interaction = {
                type: 'click',
                x: event.clientX,
                y: event.clientY,
                timestamp: Date.now(),
                target: this.getElementInfo(event.target),
                button: event.button
            };
            this.addInteraction(interaction);
        });
    }

    // Get element information (sanitized)
    getElementInfo(element) {
        if (!element) return null;

        return {
            tagName: element.tagName,
            id: element.id || null,
            className: element.className || null,
            name: element.name || null,
            type: element.type || null
        };
    }

    // Add interaction to batch and schedule send
    addInteraction(interaction) {
        this.interactions.push(interaction);

        // Clear existing timer
        if (this.batchTimer) {
            clearTimeout(this.batchTimer);
        }

        // Send immediately if batch size reached
        if (this.interactions.length >= this.batchSize) {
            this.sendBatch();
        } else {
            // Schedule send after max wait time
            this.batchTimer = setTimeout(() => {
                this.sendBatch();
            }, this.maxWaitTime);
        }
    }

    // Send batch to server
    async sendBatch() {
        if (this.interactions.length === 0) return;

        const batch = [...this.interactions];
        this.interactions = [];

        try {
            const response = await fetch(this.endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    interactions: batch,
                    sessionId: this.getSessionId(),
                    userAgent: navigator.userAgent,
                    timestamp: Date.now()
                })
            });

            if (!response.ok) {
                console.warn('Failed to log interactions:', response.status);
                // Optionally retry or store for later
            }
        } catch (error) {
            console.error('Error logging interactions:', error);
            // Optionally store in local storage for later sync
        }
    }

    // Generate session ID
    getSessionId() {
        let sessionId = sessionStorage.getItem('userSessionId');
        if (!sessionId) {
            sessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            sessionStorage.setItem('userSessionId', sessionId);
        }
        return sessionId;
    }

    // Handle page unload to send remaining interactions
    setupBeforeUnloadListener() {
        window.addEventListener('beforeunload', () => {
            if (this.interactions.length > 0) {
                // Use sendBeacon for more reliable unload sending
                const blob = new Blob([JSON.stringify({
                    interactions: this.interactions,
                    sessionId: this.getSessionId(),
                    isUnload: true,
                    timestamp: Date.now()
                })], { type: 'application/json' });

                navigator.sendBeacon(this.endpoint, blob);
            }
        });
    }

    // Disable logging (for GDPR compliance, user preferences)
    disable() {
        this.isEnabled = false;
        this.interactions = [];
        if (this.batchTimer) {
            clearTimeout(this.batchTimer);
        }
    }

    // Enable logging
    enable() {
        this.isEnabled = true;
        this.init();
    }
}

