                    position: { x: e.clientX, y: e.clientY },
                    timestamp: Date.now()
                });
            }, 500);
        });

        // Track page leave
        document.addEventListener('mouseleave', (e) => {
            this.logInteraction({
                type: 'mouse_leave',
                timestamp: Date.now()
            });
        });

        // Track key presses (for forms and search)
        document.addEventListener('keydown', (e) => {
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
                this.logInteraction({
                    type: 'key_press',
                    key: e.key,
                    target: e.target.tagName,
                    id: e.target.id || 'none',
                    timestamp: Date.now()
                });
            }
        });
    }

    logInteraction(interaction) {
        const interactionWithSession = {
            ...interaction,
            sessionDuration: Date.now() - this.startTime,
            url: window.location.href,
            userAgent: navigator.userAgent
        };

        this.interactions.push(interactionWithSession);

        // Optional: Send to analytics endpoint
        this.sendToAnalytics(interactionWithSession);

        // Optional: Console log for debugging
        console.log('User interaction:', interactionWithSession);
    }

    sendToAnalytics(interaction) {
