    // Get all interactions
    getInteractions() {
        return this.interactions;
    }

    // Clear interactions
    clearInteractions() {
        this.interactions = [];
    }

    // Get interaction summary
    getSummary() {
        const summary = {
            totalInteractions: this.interactions.length,
            sessionDuration: Date.now() - this.startTime,
            interactionTypes: {},
            mostActiveElement: this.getMostActiveElement()
        };

        this.interactions.forEach(interaction => {
            summary.interactionTypes[interaction.type] = 
                (summary.interactionTypes[interaction.type] || 0) + 1;
        });

        return summary;
    }

    getMostActiveElement() {
        const elementCounts = {};
        this.interactions.forEach(interaction => {
            if (interaction.element && interaction.id !== 'none') {
                const key = `${interaction.element}#${interaction.id}`;
                elementCounts[key] = (elementCounts[key] || 0) + 1;
            }
        });

        return Object.keys(elementCounts).reduce((a, b) => 
            elementCounts[a] > elementCounts[b] ? a : b, 'none');
    }
}

