class UserActivityLogger {
    constructor(analyticsEndpoint, options = {}) {
        this.analyticsEndpoint = analyticsEndpoint;
        this.options = {
            trackClicks: options.trackClicks !== false,
            trackKeystrokes: options.trackKeystrokes !== false,
            trackScroll: options.trackScroll || false,
            sampleRate: options.sampleRate || 1.0,
            batchSize: options.batchSize || 10,
            debounceDelay: options.debounceDelay || 1000
        };

        this.eventQueue = [];
        this.isSending = false;

        this.init();
    }

    init() {
        if (this.options.trackClicks) {
            this.setupClickTracking();
        }

        if (this.options.trackKeystrokes) {
            this.setupKeystrokeTracking();
        }

        if (this.options.trackScroll) {
            this.setupScrollTracking();
        }

        // Set up periodic sending
        setInterval(() => this.sendBatch(), 30000); // Send every 30 seconds
    }

    setupClickTracking() {
        document.addEventListener('click', (event) => {
            if (Math.random() > this.options.sampleRate) return;

            const target = event.target;
            const activity = {
                type: 'click',
                timestamp: Date.now(),
                element: {
                    tag: target.tagName,
                    id: target.id || null,
                    classes: target.className || null,
                    text: target.textContent?.trim().slice(0, 100) || null
                },
                position: {
                    x: event.clientX,
                    y: event.clientY
                },
                url: window.location.href,
                userAgent: navigator.userAgent
            };

            this.queueActivity(activity);
        }, true);
    }

    setupKeystrokeTracking() {
        let keystrokeBuffer = '';
        let lastKeystrokeTime = Date.now();

        document.addEventListener('keydown', (event) => {
            if (Math.random() > this.options.sampleRate) return;

            const now = Date.now();

            // Group keystrokes that happen close together
            if (now - lastKeystrokeTime > 1000 && keystrokeBuffer) {
                this.logKeystrokeGroup(keystrokeBuffer);
                keystrokeBuffer = '';
            }

            // Ignore modifier keys and special keys
            if (event.key.length === 1) {
                keystrokeBuffer += event.key;
            }

            lastKeystrokeTime = now;

            // Log individual key press for special keys
            if (event.key.length > 1) {
                const activity = {
                    type: 'keystroke',
                    subtype: 'special_key',
                    timestamp: Date.now(),
                    key: event.key,
                    code: event.code,
                    target: this.getElementInfo(event.target),
                    url: window.location.href
                };

                this.queueActivity(activity);
            }
        });

        // Log remaining buffer when user stops typing
        document.addEventListener('click', () => {
            if (keystrokeBuffer) {
                this.logKeystrokeGroup(keystrokeBuffer);
                keystrokeBuffer = '';
            }
        });
    }

    logKeystrokeGroup(keystrokes) {
        const activity = {
            type: 'keystroke',
            subtype: 'character_group',
            timestamp: Date.now(),
            characters: keystrokes,
            characterCount: keystrokes.length,
            url: window.location.href
        };

        this.queueActivity(activity);
    }

    setupScrollTracking() {
        let scrollTimeout;

        window.addEventListener('scroll', () => {
            clearTimeout(scrollTimeout);
            scrollTimeout = setTimeout(() => {
                if (Math.random() > this.options.sampleRate) return;

                const activity = {
                    type: 'scroll',
                    timestamp: Date.now(),
                    position: {
                        x: window.scrollX,
                        y: window.scrollY
                    },
                    viewport: {
                        width: window.innerWidth,
                        height: window.innerHeight
                    },
                    url: window.location.href
                };

                this.queueActivity(activity);
            }, this.options.debounceDelay);
        });
    }

    getElementInfo(element) {
        return {
            tag: element?.tagName || null,
            id: element?.id || null,
            classes: element?.className || null,
            type: element?.type || null,
            name: element?.name || null
        };
    }

    queueActivity(activity) {
        this.eventQueue.push(activity);

        // Send batch if queue reaches batch size
        if (this.eventQueue.length >= this.options.batchSize) {
            this.sendBatch();
        }
    }

    async sendBatch() {
        if (this.isSending || this.eventQueue.length === 0) {
            return;
        }

        this.isSending = true;
        const batch = this.eventQueue.splice(0, this.options.batchSize);

        try {
            const response = await fetch(this.analyticsEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    events: batch,
                    sessionId: this.getSessionId(),
                    timestamp: Date.now()
                })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            console.log(`Successfully sent ${batch.length} events to analytics server`);
        } catch (error) {
            console.error('Failed to send analytics data:', error);
            // Requeue failed events
            this.eventQueue.unshift(...batch);
        } finally {
            this.isSending = false;
        }
    }

    getSessionId() {
        if (!sessionStorage.userActivitySessionId) {
            sessionStorage.userActivitySessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
        }
        return sessionStorage.userActivitySessionId;
    }

    // Method to manually flush the queue
    flush() {
        return this.sendBatch();
    }

    // Method to destroy the logger and clean up event listeners
    destroy() {
        // In a real implementation, you would remove event listeners here
        this.flush();
    }
}

