I'll help you create a basic user authentication system using JavaScript. Let me break this down into manageable steps and provide you with a comprehensive implementation.

## Basic User Authentication System in JavaScript

Here's a simple implementation that includes user registration, login, password hashing, and token storage:

```javascript
// Authentication System Class
class AuthSystem {
    constructor() {
        this.users = JSON.parse(localStorage.getItem('users')) || {};
        this.currentUser = null;
        this.tokens = JSON.parse(localStorage.getItem('tokens')) || {};
    }

    // Hash password using simple bcrypt-like approach
    async hashPassword(password) {
        const encoder = new TextEncoder();
        const data = encoder.encode(password);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    }

    // Generate random token
    generateToken() {
        return Math.random().toString(36).substring(2) + 
               Date.now().toString(36) + 
               Math.random().toString(36).substring(2);
    }

    // Register new user
    async register(username, password, email = '') {
        if (this.users[username]) {
            throw new Error('Username already exists');
        }

        if (password.length < 6) {
            throw new Error('Password must be at least 6 characters long');
        }

        const hashedPassword = await this.hashPassword(password);
        this.users[username] = {
            username,
            password: hashedPassword,
            email,
            createdAt: new Date().toISOString()
        };

        this.saveUsers();
        return this.login(username, password);
    }

    // Login user
    async login(username, password) {
        const user = this.users[username];
        if (!user) {
            throw new Error('Invalid username or password');
        }

        const hashedPassword = await this.hashPassword(password);
        if (user.password !== hashedPassword) {
            throw new Error('Invalid username or password');
        }

        const token = this.generateToken();
        this.tokens[token] = {
            username,
            createdAt: new Date().toISOString(),
            expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() // 24 hours
        };

        this.currentUser = user;
        this.saveTokens();
        localStorage.setItem('currentToken', token);

        return { user, token };
    }

    // Validate token
    validateToken(token) {
        const tokenData = this.tokens[token];
        if (!tokenData) {
            return false;
        }

        if (new Date(tokenData.expiresAt) < new Date()) {
            delete this.tokens[token];
            this.saveTokens();
            return false;
        }

        return tokenData;
    }

    // Get current user
    getCurrentUser() {
        const token = localStorage.getItem('currentToken');
        if (!token) return null;

        const validToken = this.validateToken(token);
        if (!validToken) {
            localStorage.removeItem('currentToken');
            return null;
        }

        this.currentUser = this.users[validToken.username];
        return this.currentUser;
    }

    // Logout user
    logout() {
        const token = localStorage.getItem('currentToken');
        if (token) {
            delete this.tokens[token];
            this.saveTokens();
        }
        localStorage.removeItem('currentToken');
        this.currentUser = null;
    }

    // Save data to localStorage
    saveUsers() {
        localStorage.setItem('users', JSON.stringify(this.users));
    }

    saveTokens() {
        localStorage.setItem('tokens', JSON.stringify(this.tokens));
    }
}

// HTML Implementation Example
document.addEventListener('DOMContentLoaded', function() {
    const auth = new AuthSystem();

    // Check if user is already logged in
    const currentUser = auth.getCurrentUser();
    if (currentUser) {
        showDashboard(currentUser);
    } else {
        showLoginForm();
    }

    function showLoginForm() {
        document.getElementById('app').innerHTML = `
            <div class="auth-container">
                <h2>Login</h2>
                <form id="loginForm">
                    <input type="text" id="username" placeholder="Username" required>
                    <input type="password" id="password" placeholder="Password" required>
                    <button type="submit">Login</button>
                </form>
                <button onclick="showRegisterForm()">Don't have an account? Register</button>
            </div>
        `;

        document.getElementById('loginForm').addEventListener('submit', async function(e) {
            e.preventDefault();
            const username = document.getElementById('username').value;
            const password = document.getElementById('password').value;

            try {
                const result = await auth.login(username, password);
                showDashboard(result.user);
            } catch (error) {
                alert(error.message);
            }
        });
    }

    function showRegisterForm() {
        document.getElementById('app').innerHTML = `
            <div class="auth-container">
                <h2>Register</h2>
                <form id="registerForm">
                    <input type="text" id="newUsername" placeholder="Username" required>
                    <input type="email" id="email" placeholder="Email (optional)">
                    <input type="password" id="newPassword" placeholder="Password" required>
                    <input type="password" id="confirmPassword" placeholder="Confirm Password" required>
                    <button type="submit">Register</button>
                </form>
                <button onclick="showLoginForm()">Already have an account? Login</button>
            </div>
        `;

        document.getElementById('registerForm').addEventListener('submit', async function(e) {
            e.preventDefault();
            const username = document.getElementById('newUsername').value;
            const email = document.getElementById('email').value;
            const password = document.getElementById('newPassword').value;
            const confirmPassword = document.getElementById('confirmPassword').value;

            if (password !== confirmPassword) {
                alert('Passwords do not match');
                return;
            }

            try {
                const result = await auth.register(username, password, email);
                showDashboard(result.user);
            } catch (error) {
                alert(error.message);
            }
        });
    }

    function showDashboard(user) {
        document.getElementById('app').innerHTML = `
            <div class="dashboard">
                <h2>Welcome, ${user.username}!</h2>
                <p>Email: ${user.email || 'Not provided'}</p>
                <p>Member since: ${new Date(user.createdAt).toLocaleDateString()}</p>
                <button onclick="logout()">Logout</button>
            </div>
        `;
    }

    // Make functions globally available
    window.showLoginForm = showLoginForm;
    window.showRegisterForm = showRegisterForm;
    window.logout = function() {
        auth.logout();
        showLoginForm();
    };
});

